function endsGame(nums) {
  const n = nums.length, dp = Array.from({ length: n }, () => Array(n).fill(0)) //@init
  for (let i = 0; i < n; i++) dp[i][i] = nums[i] //@single
  for (let len = 2; len <= n; len++) {
    for (let i = 0; i + len - 1 < n; i++) {
      const j = i + len - 1; dp[i][j] = Math.max(nums[i] - dp[i + 1][j], nums[j] - dp[i][j - 1]) //@fill
    }
  }
  return dp[0][n - 1] //@done
}

