  const n = s.length
  const pal = Array.from({ length: n }, () => Array(n).fill(false))
  let count = 0
  for (let len = 1; len <= n; len++) {
    for (let i = 0; i + len - 1 < n; i++) {
      const j = i + len - 1
      if (s[i] === s[j]) {
        pal[i][j] = true
        count++
      }
    }
  }
  return count
}

